using Microsoft.OpenApi.Models;
using Microsoft.OpenApi.Readers;

string yaml = File.ReadAllText("petstore.yaml");
OpenApiStringReader reader = new OpenApiStringReader();
OpenApiDocument doc = reader.Read(yaml, out var diag);

Console.WriteLine($"Title: {doc.Info.Title}");
Console.WriteLine($"Version: {doc.Info.Version}");
Console.WriteLine($"Paths: {doc.Paths.Count}");

foreach (var path in doc.Paths)
{
    Console.WriteLine($"Path: {path.Key}");
}

foreach (var server in doc.Servers)
{
    Console.WriteLine($"Server: {server.Url}");
}

OpenApiDocument doc = new OpenApiDocument
{
    Info = new OpenApiInfo { Title = "My API", Version = "v1" },
    Servers = new List<OpenApiServer>
    {
        new OpenApiServer { Url = "https://api.example.com" }
    },
    Paths = new OpenApiPathItem
    {
        ["/hello"] = new OpenApiPathItem
        {
            Operations = {
                [OperationType.Get] = new OpenApiOperation
                {
                    Summary = "Say hello",
                    Responses = {
                        ["200"] = new OpenApiResponse { Description = "Success" }
                    }
                }
            }
        }
    }
};

OpenApiYamlWriter yamlWriter = new OpenApiYamlWriter();
yamlWriter.Write(doc, Console.OpenStandardOutput());
